using System;
using UnityEngine;

namespace Portfolio.DeathRace
{
    /// <summary>The sounds of a race and its menus (generated by the art builder).</summary>
    [Serializable]
    public sealed class RaceSounds
    {
        public AudioClip engine;
        public AudioClip skid;
        public AudioClip gun;
        public AudioClip ricochet;
        public AudioClip impact;
        public AudioClip scrape;
        public AudioClip explosion;
        public AudioClip bigExplosion;
        public AudioClip mineDrop;
        public AudioClip mineArm;
        public AudioClip rocketLaunch;
        public AudioClip nitro;
        public AudioClip pickupCash;
        public AudioClip pickupRepair;
        public AudioClip pickupAmmo;
        public AudioClip pickupNitro;
        public AudioClip countdown;
        public AudioClip go;
        public AudioClip lap;
        public AudioClip finish;
        public AudioClip wreckJingle;
        public AudioClip victory;
        public AudioClip buy;
        public AudioClip sell;
        public AudioClip deny;
        public AudioClip click;
        public AudioClip menuMusic;
        public AudioClip raceMusic;
    }

    /// <summary>
    /// What a race is built from that does not change with the look: the car models (visual prefabs with a
    /// <see cref="CarModelView"/>; the race adds the physics and the weapons when it spawns one), the mines, rockets and
    /// pickups, the effects and the sounds. One asset, <c>Config/DeathRaceContent.asset</c>, made by the builders.
    /// </summary>
    [CreateAssetMenu(fileName = "DeathRaceContent", menuName = "Death Race/Content")]
    public class DeathRaceContent : ScriptableObject
    {
        [Tooltip("Per CarModel.")]
        public GameObject[] carPrefabs = new GameObject[0];
        public GameObject mine;
        public GameObject rocket;
        [Tooltip("Per PickupKind.")]
        public GameObject[] pickups = new GameObject[0];

        [Header("Effects")]
        public GameObject explosion;
        public GameObject bigExplosion;
        public GameObject sparks;
        public GameObject smoke;
        public GameObject blackSmoke;
        public GameObject muzzleFlash;
        public GameObject fire;
        public GameObject nitroFlame;
        public GameObject dust;
        public GameObject scorch;
        public Material tracer;
        public Material skid;

        [Header("Sound")]
        public RaceSounds sounds = new RaceSounds();

        public GameObject CarPrefab(CarModel model)
        {
            int index = (int)model;
            return carPrefabs != null && index >= 0 && index < carPrefabs.Length ? carPrefabs[index] : null;
        }

        public GameObject Pickup(PickupKind kind)
        {
            int index = (int)kind;
            return pickups != null && index >= 0 && index < pickups.Length ? pickups[index] : null;
        }
    }
}
